  function f(v){return String(Math.round(v*100)/100);}
  function clamp(v){return v<0?0:(v>1?1:v);}

  function pose(t){
    t=t%PERIOD; if(t<0){t+=PERIOD;}
    var n=T.length;
    if(t>=T[n-1]){return K[n-1];}
    var i=0;
    while(i<n-2&&t>=T[i+1]){i++;}
    var u=(t-T[i])/(T[i+1]-T[i]);
    var a=K[i],b=K[i+1],o={},k,j,x,y,r;
    for(k in a){
      if(Object.prototype.hasOwnProperty.call(a,k)){
        x=a[k];y=b[k];r=new Array(x.length);
        for(j=0;j<x.length;j++){r[j]=x[j]+(y[j]-x[j])*u;}
        o[k]=r;
      }
    }
    return o;
  }

  function spline(p){
    var n=p.length/2,d='M'+f(p[0])+','+f(p[1]),i,i0,i2,i3,x0,y0,x1,y1,x2,y2,x3,y3;
