      i0=(i-1+n)%n;i2=(i+1)%n;i3=(i+2)%n;
      x0=p[2*i0];y0=p[2*i0+1];x1=p[2*i];y1=p[2*i+1];
      x2=p[2*i2];y2=p[2*i2+1];x3=p[2*i3];y3=p[2*i3+1];
